<button class="btn btn--lg btn--icon btn--round" data-status="busy">
  <svg class="status-ring" viewBox="0 0 40 40"><circle cx="20" cy="20" r="19" pathLength="100"/></svg>
  <span class="agent__mark">Ab</span>
</button>
